# 장난감: 층마다 공급자가 고장 없이 돌아갈 확률 p, 층 수 n
def chain(p, n_layers, suppliers):
    layer_ok = 1 - (1 - p) ** suppliers   # 공급자 중 하나라도 살아 있으면 그 층은 돈다
    return layer_ok ** n_layers           # 모든 층이 다 돌아야 칩이 나온다

for k in (1, 2, 3):
    print(f"층당 공급자 {k}곳: {chain(0.95, 3, k):.4f}")

# 장난감 단가($/백만 토큰): 닫힌 API vs 여러 호스트가 경쟁하는 열린 가중치 모델
closed = {"in": 3.0, "out": 15.0}
open_ = {"in": 0.3, "out": 0.9}
use = {"in": 800e6, "out": 200e6}            # 한 달 입력 8억, 출력 2억 토큰
def bill(p):
    return sum(p[k] * use[k] / 1e6 for k in use)
print("닫힌:", bill(closed), "열린:", bill(open_), "배수:", bill(closed) / bill(open_))

# 장난감 두 부문: 임금이 경제 전체에서 20% 오르고,
# 소프트웨어 생산성은 50% 오르고 의료 생산성은 그대로
wage = 1.20
prod = {"software": 1.50, "health": 1.00}
for s, a in prod.items():
    print(s, "가격 배수:", round(wage / a, 3))   # 단위 노동비 = 임금 / 생산성
# 성장 근사: GDP 성장 ≈ Σ 지출 몫 × 부문 생산성 성장
for share in (0.10, 0.05):
    print(f"소프트웨어 몫 {share:.0%}: GDP ≈ +{share * 0.50:.1%}")
